from decimal import Decimal, ROUND_HALF_UP

_CENTS = Decimal("0.01")


def to_money(amount):
    """Convert an amount to an exact Decimal.

    Goes via str() because that gives the shortest repr that round-trips, so a
    price written as 0.145 becomes exactly 0.145 rather than the binary float
    0.14499999999999999000799880510... that Decimal(float) would produce.
    """
    return Decimal(str(amount))


def sum_money(amounts):
    """Sum monetary amounts exactly, without float drift."""
    return sum((to_money(a) for a in amounts), Decimal(0))


def round_money(amount):
    """Round a monetary amount to 2 decimal places, half away from zero."""
    return float(to_money(amount).quantize(_CENTS, rounding=ROUND_HALF_UP))

